/**
 * Main JavaScript file for SecureFish Technologies Website
 * 
 * This file contains all frontend logic, component implementations,
 * state management, and API interactions for the website.
 * 
 * @file public/js/main.js
 * @version 1.0.0
 * @author SecureFish Technologies
 */

// State Management
const State = {
  /**
   * Get cart from localStorage
   * @returns {Array} Array of cart items
   */
  getCart: () => {
    try {
      const cart = localStorage.getItem('cart');
      return cart ? JSON.parse(cart) : [];
    } catch (error) {
      console.error('Error loading cart from localStorage:', error);
      return [];
    }
  },

  /**
   * Save cart to localStorage
   * @param {Array} cart - Array of cart items
   */
  saveCart: (cart) => {
    try {
      localStorage.setItem('cart', JSON.stringify(cart));
    } catch (error) {
      console.error('Error saving cart to localStorage:', error);
    }
  },

  /**
   * Get user session from sessionStorage
   * @returns {Object|null} User session object or null
   */
  getUserSession: () => {
    try {
      const session = sessionStorage.getItem('userSession');
      return session ? JSON.parse(session) : null;
    } catch (error) {
      console.error('Error loading user session:', error);
      return null;
    }
  },

  /**
   * Save user session to sessionStorage
   * @param {Object} session - User session object
   */
  saveUserSession: (session) => {
    try {
      sessionStorage.setItem('userSession', JSON.stringify(session));
    } catch (error) {
      console.error('Error saving user session:', error);
    }
  },

  /**
   * Clear user session
   */
  clearUserSession: () => {
    try {
      sessionStorage.removeItem('userSession');
    } catch (error) {
      console.error('Error clearing user session:', error);
    }
  },

  /**
   * Get theme preference from localStorage
   * @returns {string} Theme preference ('light' or 'dark')
   */
  getTheme: () => {
    try {
      return localStorage.getItem('theme') || 'light';
    } catch (error) {
      console.error('Error loading theme preference:', error);
      return 'light';
    }
  },

  /**
   * Save theme preference to localStorage
   * @param {string} theme - Theme preference ('light' or 'dark')
   */
  saveTheme: (theme) => {
    try {
      localStorage.setItem('theme', theme);
    } catch (error) {
      console.error('Error saving theme preference:', error);
    }
  }
};

// API Service
const ApiService = {
  /**
   * Generic API request handler
   * @param {string} url - API endpoint
   * @param {Object} options - Fetch options
   * @returns {Promise<Object>} API response
   */
  request: async (url, options = {}) => {
    const defaultOptions = {
      headers: {
        'Content-Type': 'application/json',
      },
    };

    try {
      const response = await fetch(url, { ...defaultOptions, ...options });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error(`API request failed: ${error.message}`);
      throw error;
    }
  },

  /**
   * Fetch products from API
   * @returns {Promise<Array>} Array of products
   */
  fetchProducts: async () => {
    return await ApiService.request('/api/products');
  },

  /**
   * User login
   * @param {Object} credentials - User credentials
   * @returns {Promise<Object>} Login response
   */
  login: async (credentials) => {
    return await ApiService.request('/api/login', {
      method: 'POST',
      body: JSON.stringify(credentials)
    });
  },

  /**
   * Submit contact form
   * @param {Object} contactData - Contact form data
   * @returns {Promise<Object>} Contact submission response
   */
  submitContact: async (contactData) => {
    return await ApiService.request('/api/contact', {
      method: 'POST',
      body: JSON.stringify(contactData)
    });
  }
};

// Hero Section Component
const HeroSection = {
  /**
   * Initialize hero section
   */
  init: () => {
    const ctaButton = document.querySelector('.hero-cta');
    if (ctaButton) {
      ctaButton.addEventListener('click', HeroSection.handleCTAClick);
    }
    HeroSection.animateHeroElements();
  },

  /**
   * Handle CTA button click
   * @param {Event} event - Click event
   */
  handleCTAClick: (event) => {
    event.preventDefault();
    const targetSection = document.querySelector('#products');
    if (targetSection) {
      targetSection.scrollIntoView({ behavior: 'smooth' });
    }
  },

  /**
   * Animate hero elements on page load
   */
  animateHeroElements: () => {
    const heroElements = document.querySelectorAll('.hero-element');
    heroElements.forEach((element, index) => {
      setTimeout(() => {
        element.classList.add('animate');
      }, 300 * index);
    });
  }
};

// Product Catalog Component
const ProductCatalog = {
  /**
   * Initialize product catalog
   */
  init: () => {
    ProductCatalog.bindEvents();
    ProductCatalog.fetchProducts();
  },

  /**
   * Bind event listeners
   */
  bindEvents: () => {
    const searchInput = document.querySelector('#product-search');
    const filterForm = document.querySelector('#product-filters');

    if (searchInput) {
      searchInput.addEventListener('input', ProductCatalog.handleSearch);
    }

    if (filterForm) {
      filterForm.addEventListener('submit', (e) => {
        e.preventDefault();
        ProductCatalog.applyFilters();
      });
    }
  },

  /**
   * Handle search input
   * @param {Event} event - Input event
   */
  handleSearch: (event) => {
    const searchTerm = event.target.value.toLowerCase();
    const products = document.querySelectorAll('.product-item');

    products.forEach(product => {
      const productName = product.querySelector('.product-name').textContent.toLowerCase();
      if (productName.includes(searchTerm)) {
        product.style.display = 'block';
      } else {
        product.style.display = 'none';
      }
    });
  },

  /**
   * Fetch products from API
   */
  fetchProducts: async () => {
    const productContainer = document.querySelector('#product-container');
    const loadingIndicator = document.querySelector('#product-loading');

    if (!productContainer || !loadingIndicator) return;

    try {
      loadingIndicator.style.display = 'block';
      const products = await ApiService.fetchProducts();
      ProductCatalog.renderProducts(products);
    } catch (error) {
      productContainer.innerHTML = '<p class="error">Failed to load products. Please try again later.</p>';
    } finally {
      loadingIndicator.style.display = 'none';
    }
  },

  /**
